//! A small tree-ensemble model: the feature vector it reads, and an
//! evaluator that says how much each feature moved the result.
//!
//! The model runs in shadow: its score is recorded beside the rule score and
//! changes no action. It is trained by `tools/train/train.py`.
//!
//! FIXED BY THE PROJECT LEAD: DO NOT EDIT this file, `features.rs`,
//! `data/features_v1.json` or `examples/eval.rs`. Implement `tree.rs`. A
//! model file may come from a feed, so every byte of it is untrusted until
//! it has been validated: nothing may panic, loop without bound or recurse
//! without bound.
//!
//! # Model file, version 1
//!
//! ```json
//! {
//!   "v": 1,
//!   "features": ["n_identity", "pen_identity", "..."],
//!   "base": -0.25,
//!   "trees": [
//!     [ {"f": 3, "t": 0.5, "l": 1, "r": 2, "v": 0.1}, {"v": -0.4}, {"v": 0.6} ]
//!   ]
//! }
//! ```
//!
//! A tree is an array of nodes; node 0 is its root. A node is either
//!
//! - a **split**: exactly the keys `f` (feature index), `t` (threshold),
//!   `l` and `r` (indices of the children in the same array) and `v`, or
//! - a **leaf**: exactly the key `v`.
//!
//! `v` is the value of the node: for a leaf, what it adds to the result; for
//! a split, the expected value of its subtree over the training data.
//! Evaluation starts at the root and at each split goes to `l` when
//! `x[f] < t` and to `r` otherwise. A feature value that is NaN goes to `l`.
//!
//! - `raw` = `base` + the sum over trees of the value of the leaf reached.
//! - `probability` = `1 / (1 + exp(-raw))`: how likely the client is automated.
//! - `bias` = `base` + the sum over trees of the root's `v`.
//! - `contributions[f]` = the sum, over every split on feature `f` that was
//!   passed, of `v(child taken) - v(split)`.
//!
//! So `raw == bias + sum(contributions)` up to rounding.
//!
//! # What is refused at load
//!
//! | Error | When |
//! |---|---|
//! | `TooLarge` | the file is longer than `MAX_MODEL_BYTES` (checked first) |
//! | `Malformed` | not JSON; not this shape; a node that is neither a split nor a leaf; an unknown key anywhere; a number that is not finite or an index that is negative or fractional |
//! | `Version` | `v` is not 1 |
//! | `Limits` | more than `MAX_FEATURES` features, `MAX_TREES` trees or `MAX_NODES` nodes in a tree; a leaf deeper than `MAX_DEPTH` (the root is at depth 0); a feature name that is empty or longer than `MAX_NAME_BYTES` |
//! | `Structure` | a tree with no nodes; a child index that is not greater than its parent's index (this is what rules out a cycle) or is past the end; a feature index past the end of `features`; a feature name used twice |
//!
//! Checks are made in that order. A model with no trees is valid.

mod features;
mod tree;

use std::fmt;

pub use features::{FeatureSpec, BUILTIN_FEATURES};
pub use tree::Model;

pub const MAX_MODEL_BYTES: usize = 1024 * 1024;
pub const MAX_FEATURES: usize = 256;
pub const MAX_TREES: usize = 512;
pub const MAX_NODES: usize = 1023;
pub const MAX_DEPTH: usize = 10;
pub const MAX_NAME_BYTES: usize = 64;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ModelError {
    TooLarge,
    Malformed,
    Version,
    Limits,
    Structure,
}

impl fmt::Display for ModelError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            ModelError::TooLarge => "model file too large",
            ModelError::Malformed => "model file malformed",
            ModelError::Version => "unsupported model version",
            ModelError::Limits => "model exceeds a size or depth limit",
            ModelError::Structure => "model structure invalid",
        })
    }
}

impl std::error::Error for ModelError {}

/// The result of evaluating a model on one feature vector.
#[derive(Clone, Debug, PartialEq)]
pub struct Evaluation {
    pub raw: f64,
    pub probability: f64,
    pub bias: f64,
    /// One entry per feature, in the model's feature order.
    pub contributions: Vec<f64>,
}

impl Evaluation {
    /// The model's verdict on the gateway's scale: 99 when it is sure the
    /// client is a person, 1 when it is sure it is automated.
    /// `round(99 - 98 * probability)`, kept within 1..=99.
    pub fn score(&self) -> u8 {
        let s = (99.0 - 98.0 * self.probability).round();
        if s.is_nan() {
            return 50;
        }
        s.clamp(1.0, 99.0) as u8
    }

    /// The `n` features that moved the result most: `(feature index,
    /// contribution)`, largest absolute contribution first, ties by lower
    /// index, features with a contribution of exactly zero left out.
    pub fn top(&self, n: usize) -> Vec<(usize, f64)> {
        let mut all: Vec<(usize, f64)> = self
            .contributions
            .iter()
            .copied()
            .enumerate()
            .filter(|(_, c)| *c != 0.0)
            .collect();
        all.sort_by(|a, b| b.1.abs().total_cmp(&a.1.abs()).then(a.0.cmp(&b.0)));
        all.truncate(n);
        all
    }
}
